<template>
  <div class="experience-container">
    <canvas ref="canvasRef" class="webgl-canvas"></canvas>
    <header class="header"><div class="logo">space<span class="logo-accent">edu</span></div><nav class="nav-links"><a href="#planets" class="active">Planets</a><a href="#trailer">Trailer</a><a href="#tickets">Tickets</a><a href="#blog">Blog</a></nav><button class="btn-enroll">Enroll</button></header>
    <section id="planets" class="section hero-section"><div class="hero-content"><span class="subtitle">PLANET</span><h1 class="title">{{ currentPlanet.name }}</h1><p class="description">{{ currentPlanet.heroDescription }}</p><button class="btn-primary" @click="scrollToNextSection">GET STARTED</button></div>
      <button class="adjacent-planet left-planet" :aria-label="`View ${previousPlanet.name}`" @click="selectPlanet(currentIndex - 1)"><span class="planet-thumb" :style="thumbnailStyle(previousPlanet)"></span><span>{{ previousPlanet.name }}</span></button>
      <button class="adjacent-planet right-planet" :aria-label="`View ${nextPlanet.name}`" @click="selectPlanet(currentIndex + 1)"><span class="planet-thumb" :style="thumbnailStyle(nextPlanet)"></span><span>{{ nextPlanet.name }}</span></button>
      <div class="scroll-indicator" @click="scrollToNextSection"><svg viewBox="0 0 24 24" width="24" height="24" stroke="currentColor" stroke-width="2" fill="none"><path d="M7 13l5 5 5-5M7 6l5 5 5-5" /></svg></div>
    </section>
    <section class="section detail-section"><div class="detail-content"><span class="tagline">{{ currentPlanet.tagline }}</span><h2 class="detail-title">{{ currentPlanet.name }}</h2><p class="detail-description">{{ currentPlanet.detailedInfo }}</p><div class="actions"><button class="btn-primary" @click="selectPlanet(currentIndex + 1)">NEXT PLANET</button><button class="btn-play" aria-label="Play video"><svg viewBox="0 0 24 24" width="16" height="16" fill="currentColor"><polygon points="5 3 19 12 5 21 5 3" /></svg></button></div></div></section>
    <section class="section surface-section"><div class="surface-content"><p class="surface-description">{{ currentPlanet.surfaceInfo }}</p></div></section>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref } from 'vue'
import * as THREE from 'three'
import gsap from 'gsap'
import { ScrollTrigger } from 'gsap/ScrollTrigger'
gsap.registerPlugin(ScrollTrigger)

type Planet = { id: string; name: string; tagline: string; heroDescription: string; detailedInfo: string; surfaceInfo: string; texture: string }
const canvasRef = ref<HTMLCanvasElement | null>(null)
const currentIndex = ref(2)
const textureBase = 'https://www.solarsystemscope.com/textures/download/'
const blueprints = [
  ['mercure', 'MERCURY', 'THE SWIFT PLANET', '2k_mercury.jpg', 'The smallest planet is a rocky world covered by ancient impact craters. Its thin atmosphere cannot hold on to heat, so temperatures swing dramatically between day and night.'],
  ['venus', 'VENUS', 'THE VEILED PLANET', '2k_venus_surface.jpg', 'Venus is wrapped in a dense carbon-dioxide atmosphere and bright clouds of sulfuric acid. Beneath them lies a volcanic surface under extraordinary pressure.'],
  ['terre', 'EARTH', 'THE BLUE PLANET', '2k_earth_daymap.jpg', 'Our home planet is a rocky ocean world with an active surface of mountains, valleys, plains and canyons. Liquid water covers about 70% of its surface.'],
  ['mars', 'MARS', 'THE RED PLANET', '2k_mars.jpg', 'Mars is a cold desert world marked by iron-rich dust, giant volcanoes and deep canyons. Evidence of ancient rivers and lakes makes it a key target in the search for past habitability.'],
  ['jupiter', 'JUPITER', 'THE GIANT PLANET', '2k_jupiter.jpg', 'Jupiter is the largest planet in the Solar System. Its visible surface is a turbulent atmosphere of hydrogen and helium, including the long-lived Great Red Spot.'],
  ['saturne', 'SATURN', 'THE RINGED PLANET', '2k_saturn.jpg', 'Saturn is a gas giant recognized by its luminous ring system. The rings are made mostly of countless pieces of water ice, from dust-sized grains to mountain-sized fragments.'],
  ['uranus', 'URANUS', 'THE SIDEWAYS PLANET', '2k_uranus.jpg', 'Uranus is an ice giant with a pale blue atmosphere colored by methane. Its extreme axial tilt gives it seasons unlike those of any other planet.'],
  ['neptune', 'NEPTUNE', 'THE WINDY PLANET', '2k_neptune.jpg', 'Neptune is a deep-blue ice giant far from the Sun. Its atmosphere hosts the fastest winds measured anywhere in the Solar System.']
] as const
const makePlanet = ([id, name, tagline, texture, surface]: typeof blueprints[number]): Planet => ({ id, name, tagline, texture: `${textureBase}${texture}`, surfaceInfo: surface, heroDescription: `Explore ${name[0] + name.slice(1).toLowerCase()}, one of the eight worlds orbiting our Sun.`, detailedInfo: 'Loading current planetary data...' })
const planets = ref<Planet[]>(blueprints.map(makePlanet))
const currentPlanet = computed(() => planets.value[currentIndex.value])
const previousPlanet = computed(() => planets.value[(currentIndex.value + planets.value.length - 1) % planets.value.length])
const nextPlanet = computed(() => planets.value[(currentIndex.value + 1) % planets.value.length])

let scene: THREE.Scene, camera: THREE.PerspectiveCamera, renderer: THREE.WebGLRenderer, planetMesh: THREE.Mesh<THREE.SphereGeometry, THREE.MeshStandardMaterial>, atmosphereMesh: THREE.Mesh<THREE.SphereGeometry, THREE.ShaderMaterial>, ringMesh: THREE.Mesh<THREE.RingGeometry, THREE.MeshBasicMaterial>, animationFrameId = 0
let scrollTimeline: gsap.core.Timeline | undefined
const textureLoader = new THREE.TextureLoader()
const surfaceRelief: Record<string, number> = { mercure: .18, venus: .1, terre: .22, mars: .28, jupiter: .09, saturne: .08, uranus: .04, neptune: .05 }
const fallbackTexture = (color: string) => { const canvas = document.createElement('canvas'); canvas.width = canvas.height = 2; const context = canvas.getContext('2d')!; context.fillStyle = color; context.fillRect(0, 0, 2, 2); return new THREE.CanvasTexture(canvas) }
const loadPlanetTexture = (planet: Planet) => textureLoader.load(planet.texture, (texture) => { texture.colorSpace = THREE.SRGBColorSpace; planetMesh.material.map?.dispose(); planetMesh.material.map = texture; planetMesh.material.bumpMap = texture; planetMesh.material.bumpScale = surfaceRelief[planet.id]; planetMesh.material.needsUpdate = true }, undefined, () => { planetMesh.material.map?.dispose(); planetMesh.material.map = fallbackTexture('#284e76'); planetMesh.material.bumpMap = null; planetMesh.material.needsUpdate = true })
const thumbnailStyle = (planet: Planet) => ({ backgroundImage: `url("${planet.texture}")` })
const selectPlanet = (index: number) => { currentIndex.value = (index + planets.value.length) % planets.value.length; if (planetMesh) { loadPlanetTexture(currentPlanet.value); atmosphereMesh.visible = !['mercure', 'venus'].includes(currentPlanet.value.id); ringMesh.visible = currentPlanet.value.id === 'saturne' } }

const loadPlanetData = async () => {
  try {
    const responses = await Promise.all(blueprints.map(async ([id]) => { const response = await fetch(`https://api.le-systeme-solaire.net/rest/bodies/${id}`); if (!response.ok) throw new Error(id); return response.json() }))
    planets.value = blueprints.map((blueprint, index) => { const planet = makePlanet(blueprint); const data = responses[index]; const radius = new Intl.NumberFormat('en-US').format(Math.round(data.meanRadius)); const moons = data.moons?.length ?? 0; return { ...planet, detailedInfo: `${planet.name[0] + planet.name.slice(1).toLowerCase()} has a mean radius of ${radius} km, surface gravity of ${Number(data.gravity).toFixed(2)} m/s², and ${moons} known moon${moons === 1 ? '' : 's'}. It completes an orbit around the Sun in about ${Number(data.sideralOrbit).toFixed(1)} Earth days.` } })
  } catch { planets.value = planets.value.map((planet) => ({ ...planet, detailedInfo: `${planet.name[0] + planet.name.slice(1).toLowerCase()} is one of the eight planets in our Solar System. Explore this world through its real surface texture and return later for live data.` })) }
}
const initThree = () => {
  if (!canvasRef.value) return
  scene = new THREE.Scene(); scene.fog = new THREE.FogExp2(0x050811, .05)
  camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, .1, 100); camera.position.set(0, 0, 6)
  renderer = new THREE.WebGLRenderer({ canvas: canvasRef.value, antialias: true, alpha: true }); renderer.setSize(window.innerWidth, window.innerHeight); renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2)); renderer.toneMapping = THREE.ACESFilmicToneMapping; renderer.outputColorSpace = THREE.SRGBColorSpace
  planetMesh = new THREE.Mesh(new THREE.SphereGeometry(2, 96, 96), new THREE.MeshStandardMaterial({ map: fallbackTexture('#244f79'), roughness: .72, metalness: .01 })); planetMesh.position.set(0, -1.8, 1.5); scene.add(planetMesh); loadPlanetTexture(currentPlanet.value)
  atmosphereMesh = new THREE.Mesh(new THREE.SphereGeometry(2.06, 96, 96), new THREE.ShaderMaterial({ transparent: true, side: THREE.BackSide, depthWrite: false, blending: THREE.AdditiveBlending, vertexShader: 'varying vec3 vNormal; void main() { vNormal = normalize(normalMatrix * normal); gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }', fragmentShader: 'varying vec3 vNormal; void main() { float rim = pow(0.72 - dot(vNormal, vec3(0.0, 0.0, 1.0)), 3.0); gl_FragColor = vec4(0.18, 0.55, 1.0, rim * 0.32); }' })); planetMesh.add(atmosphereMesh)
  const ringTexture = textureLoader.load(`${textureBase}2k_saturn_ring_alpha.png`); ringTexture.colorSpace = THREE.SRGBColorSpace; ringMesh = new THREE.Mesh(new THREE.RingGeometry(2.28, 3.45, 128), new THREE.MeshBasicMaterial({ map: ringTexture, alphaMap: ringTexture, color: 0xe8d5ae, transparent: true, opacity: .82, alphaTest: .06, side: THREE.DoubleSide, depthWrite: false })); ringMesh.rotation.x = Math.PI / 2; ringMesh.visible = false; planetMesh.add(ringMesh)
  const geometry = new THREE.BufferGeometry(), positions = new Float32Array(3600); for (let i = 0; i < positions.length; i += 3) { positions[i] = (Math.random() - .5) * 50; positions[i + 1] = (Math.random() - .5) * 50; positions[i + 2] = -Math.random() * 30 }; geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3)); scene.add(new THREE.Points(geometry, new THREE.PointsMaterial({ color: 0xffffff, size: .05, transparent: true, opacity: .8 })))
  scene.add(new THREE.AmbientLight(0x1a2b4c, 1.2)); const sunlight = new THREE.DirectionalLight(0xffffff, 2.5); sunlight.position.set(5, 3, 5); scene.add(sunlight)
  const animate = () => { planetMesh.rotation.y += .0015; renderer.render(scene, camera); animationFrameId = requestAnimationFrame(animate) }; animate()
}
const setupScrollAnimations = () => { scrollTimeline = gsap.timeline({ scrollTrigger: { trigger: '.experience-container', start: 'top top', end: 'bottom bottom', scrub: 1.2 } }); scrollTimeline.to(planetMesh.position, { x: 1.8, y: .1, z: 2.2, ease: 'power1.inOut' }, 0).to(planetMesh.rotation, { x: .2, y: Math.PI * .8, ease: 'none' }, 0).to('.hero-content, .adjacent-planet, .scroll-indicator', { opacity: 0, y: -50, stagger: .05 }, 0).fromTo('.detail-content', { opacity: 0, x: -80 }, { opacity: 1, x: 0, ease: 'power2.out' }, .3).to(camera.position, { z: 3.2, y: .2, ease: 'power2.inOut' }, 1).to(planetMesh.position, { x: 0, y: .5, z: 1.8, ease: 'power2.inOut' }, 1).to('.detail-content', { opacity: 0, y: -30 }, 1).fromTo('.surface-content', { opacity: 0, y: 50 }, { opacity: 1, y: 0, ease: 'power2.out' }, 1.4) }
const scrollToNextSection = () => window.scrollTo({ top: window.innerHeight, behavior: 'smooth' })
const onWindowResize = () => { if (!camera || !renderer) return; camera.aspect = window.innerWidth / window.innerHeight; camera.updateProjectionMatrix(); renderer.setSize(window.innerWidth, window.innerHeight) }
onMounted(async () => { initThree(); setupScrollAnimations(); window.addEventListener('resize', onWindowResize); await loadPlanetData() })
onUnmounted(() => { window.removeEventListener('resize', onWindowResize); cancelAnimationFrame(animationFrameId); scrollTimeline?.kill(); ScrollTrigger.getAll().forEach((trigger) => trigger.kill()); ringMesh?.geometry.dispose(); ringMesh?.material.map?.dispose(); ringMesh?.material.dispose(); atmosphereMesh?.geometry.dispose(); atmosphereMesh?.material.dispose(); planetMesh?.geometry.dispose(); planetMesh?.material.map?.dispose(); planetMesh?.material.dispose(); renderer?.dispose() })
</script>

<style scoped>
@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@500;700;800&family=Plus+Jakarta+Sans:wght@300;400;600&display=swap');
.experience-container{position:relative;width:100%;min-height:100vh;background:#050811;color:#fff;font-family:'Plus Jakarta Sans',sans-serif;overflow-x:hidden}.webgl-canvas{position:fixed;inset:0;width:100vw;height:100vh;z-index:1;pointer-events:none}.header{position:fixed;top:0;left:0;width:100%;display:flex;justify-content:space-between;align-items:center;padding:2rem 4rem;z-index:10}.logo{font-size:1.5rem;font-weight:700;letter-spacing:1px}.logo-accent{color:#63b3ed}.nav-links{display:flex;gap:2.5rem}.nav-links a{color:rgba(255,255,255,.6);text-decoration:none;font-size:.9rem;transition:color .3s}.nav-links a.active,.nav-links a:hover{color:#fff}.btn-enroll{background:rgba(255,255,255,.12);backdrop-filter:blur(10px);border:1px solid rgba(255,255,255,.2);color:#fff;padding:.6rem 1.8rem;border-radius:50px;cursor:pointer;font-weight:600}.section{position:relative;height:100vh;width:100%;display:flex;align-items:center;padding:0 6rem;z-index:2}.hero-section{flex-direction:column;justify-content:center;text-align:center}.hero-content{max-width:650px;margin-top:-5vh}.subtitle{font-size:.9rem;letter-spacing:6px;color:rgba(255,255,255,.6);display:block;margin-bottom:.5rem}.title{font-family:'Cinzel',serif;font-size:5.5rem;font-weight:700;letter-spacing:8px;margin:0 0 1.5rem}.description,.detail-description,.surface-description{font-size:.95rem;line-height:1.8;color:rgba(255,255,255,.7)}.description{margin-bottom:2.5rem}.btn-primary{background:#fff;color:#050811;border:0;padding:.9rem 2.2rem;border-radius:50px;font-size:.85rem;font-weight:700;letter-spacing:1.5px;cursor:pointer}.btn-primary:hover{transform:translateY(-2px);box-shadow:0 10px 25px rgba(255,255,255,.2)}.adjacent-planet{position:absolute;top:55%;display:flex;align-items:center;gap:1rem;padding:0;border:0;background:transparent;font:inherit;font-size:.8rem;letter-spacing:3px;color:rgba(255,255,255,.6);cursor:pointer}.left-planet{left:5rem}.right-planet{right:5rem;flex-direction:row-reverse}.planet-thumb{width:45px;height:45px;flex:0 0 45px;border-radius:50%;background-position:center;background-size:cover;box-shadow:0 0 15px rgba(255,255,255,.1)}.adjacent-planet:hover{color:#fff}.scroll-indicator{position:absolute;bottom:2.5rem;cursor:pointer;animation:bounce 2s infinite;opacity:.7}@keyframes bounce{0%,20%,50%,80%,100%{transform:translateY(0)}40%{transform:translateY(-8px)}60%{transform:translateY(-4px)}}.detail-section{justify-content:flex-start}.detail-content{max-width:480px}.tagline{font-size:.85rem;letter-spacing:4px;color:rgba(255,255,255,.5);display:block;margin-bottom:.5rem}.detail-title{font-family:'Cinzel',serif;font-size:4rem;letter-spacing:6px;margin:0 0 1.5rem}.detail-description{margin-bottom:2rem}.actions{display:flex;align-items:center;gap:1.5rem}.btn-play{width:48px;height:48px;border-radius:50%;background:rgba(255,255,255,.1);backdrop-filter:blur(10px);border:1px solid rgba(255,255,255,.2);color:#fff;display:flex;align-items:center;justify-content:center;cursor:pointer}.surface-section{justify-content:flex-end;align-items:flex-end;padding-bottom:8rem}.surface-content{max-width:420px;background:rgba(5,8,17,.6);backdrop-filter:blur(16px);padding:2rem;border-radius:16px;border:1px solid rgba(255,255,255,.08)}.surface-description{color:rgba(255,255,255,.8);margin:0}@media(max-width:768px){.header{padding:1.5rem}.nav-links,.adjacent-planet{display:none}.title{font-size:3.5rem}.detail-title{font-size:2.8rem}.section{padding:0 2rem}}
</style>
